/**
 * Loader for the bundled osu playlist (public/music/playlist.json).
 * The playlist is generated by `npm run music` (scripts/build-osu-playlist.mjs):
 * it copies up to 100 mp3 files longer than 70s from the user's osu! Songs
 * folder into the extension bundle and lists them here.
 *
 * Returns an empty array when the playlist is absent/invalid (e.g. dev
 * checkout without running `npm run music`) — the widget then simply
 * shows the local device library.
 */

export interface BundledAudioTrack {
  id: string;
  title: string;
  artist?: string;
  /** File name inside public/music (relative to the extension root). */
  file: string;
  duration?: number;
  size?: number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function toFiniteNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0
    ? value
    : undefined;
}

function toNonEmptyString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
}

/** Parse/validate an unknown playlist.json payload.
 * Accepts both the bare-array shape and the real generated shape
 * `{ version, generatedAt, ..., tracks: [...] }` written by npm run music. */
export function parseBundledPlaylist(data: unknown): BundledAudioTrack[] {
  const list: unknown[] | null = Array.isArray(data)
    ? data
    : isRecord(data) && Array.isArray(data.tracks)
      ? (data.tracks as unknown[])
      : null;
  if (list === null) return [];
  const tracks: BundledAudioTrack[] = [];
  for (const entry of list) {
    if (!isRecord(entry)) continue;
    const title = toNonEmptyString(entry.title);
    const file = toNonEmptyString(entry.file);
    if (!title || !file) continue;
    const id = toNonEmptyString(entry.id) ?? file;
    const artist = toNonEmptyString(entry.artist);
    const duration = toFiniteNumber(entry.duration);
    const size = toFiniteNumber(entry.size);
    const track: BundledAudioTrack = { id, title, file };
    if (artist) track.artist = artist;
    if (duration !== undefined) track.duration = duration;
    if (size !== undefined) track.size = size;
    tracks.push(track);
  }
  return tracks;
}

export async function loadBundledPlaylist(): Promise<BundledAudioTrack[]> {
  try {
    const res = await fetch('music/playlist.json');
    if (!res.ok) return [];
    const data = await res.json();
    return parseBundledPlaylist(data);
  } catch {
    return [];
  }
}
